#include <iostream>
#include <string>

class Weapon {
public:
    // Constructor
    Weapon(std::string name) : name(name), cooldown(0) {}

    // Method to set the cooldown time
    void setCooldown(int seconds) {
        if (seconds > 0 && seconds <= 60) {
            cooldown = seconds;
        } else {
            std::cout << "Invalid cooldown time." << std::endl;
        }
    }

    // Method to start the attack timer
    void startAttackTimer() {
        if (cooldown > 0) {
            std::cout << "The Silent Assassin has been activated!" << std::endl;
            --cooldown;
        } else {
            std::cout << "The Silent Assassin is ready." << std::endl;
        }
    }

private:
